import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.CdjpmwdR.js";const h=JSON.parse('{"title":"Agentic Engineering in Practice: Modular, Outcome‑Driven, Continuously Evolving","description":"Breaks Agent development into modular design, outcome‑driven delivery, and continuous evolution, mapping each to concrete components and practices.","frontmatter":{"category":"node/agentic","date":"2026-02-01","title":"Agentic Engineering in Practice: Modular, Outcome‑Driven, Continuously Evolving","description":"Breaks Agent development into modular design, outcome‑driven delivery, and continuous evolution, mapping each to concrete components and practices.","tags":["node/agentic","agentic","LLM","Prompt"],"image":null},"headers":[],"relativePath":"en/blogs/2026/202602-pov-agentic-engineering.md","filePath":"en/blogs/2026/202602-pov-agentic-engineering.md"}'),o={name:"en/blogs/2026/202602-pov-agentic-engineering.md"};function s(l,e,r,c,d,u){return i(),t("div",null,[...e[0]||(e[0]=[n(`<p>Borrowing from software engineering experience, you can push Agent applications along three dimensions:</p><ul><li>Modularity: standardized responsibilities, single responsibility, higher reusability</li><li>Outcome‑driven: testable, verifiable, regression‑friendly</li><li>Continuous evolution: iterative optimization, feedback loops, versioning</li></ul><h2 id="modularity" tabindex="-1">Modularity <a class="header-anchor" href="#modularity" aria-label="Permalink to &quot;Modularity&quot;">​</a></h2><blockquote><p>Prompt ≈ Code<br> Model ≈ Compiler<br> Agent ≈ Application</p></blockquote><p>At a first approximation, you can treat prompts as a new kind of high‑level programming language. It has much higher abstraction power and expressiveness, but also brings new challenges:</p><ul><li>Uncertainty: model outputs are stochastic and diverse; it is hard to guarantee consistency and predictability.</li><li>Opacity: the internal mechanisms and decision process of models are black‑box; they are hard to understand and debug.</li><li>Dependency: performance and behavior depend on training data and architecture; they are hard to control and optimize.</li><li>Safety: models may emit harmful, biased, or inappropriate content; they are hard to guard and govern.</li></ul><p>Likewise, you can see an Agent as a new application architecture with higher intelligence and autonomy.</p><h3 id="core-components-of-an-agent" tabindex="-1">Core Components of an Agent <a class="header-anchor" href="#core-components-of-an-agent" aria-label="Permalink to &quot;Core Components of an Agent&quot;">​</a></h3><h4 id="system-instruction" tabindex="-1">System Instruction <a class="header-anchor" href="#system-instruction" aria-label="Permalink to &quot;System Instruction&quot;">​</a></h4><p>Defines global rules, roles, and safety boundaries; always in effect.</p><ul><li>Similar to: environment variables or global configuration</li><li>Examples: SOUL.md, AGENT.md, CLAUDE.md</li></ul><h4 id="command" tabindex="-1">Command <a class="header-anchor" href="#command" aria-label="Permalink to &quot;Command&quot;">​</a></h4><p>Executable commands explicitly triggered by the user.</p><ul><li>Similar to: API endpoints or CLI commands</li><li>Examples: &quot;help me write an email&quot;, <code>/search AI safety papers</code></li></ul><h4 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h4><p>Capabilities the Agent can autonomously invoke.</p><ul><li>Similar to: dynamic dispatch based on conditions</li><li>Examples: pdf‑convert, code‑execution, web‑search</li></ul><h3 id="context-and-data-layer" tabindex="-1">Context and Data Layer <a class="header-anchor" href="#context-and-data-layer" aria-label="Permalink to &quot;Context and Data Layer&quot;">​</a></h3><h4 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h4><p>Cross‑session state and preferences, ensuring continuity.</p><ul><li>Similar to: database or cache</li><li>Examples: user profile memory, task state memory</li></ul><h4 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h4><p>External capability integration; provides data and interfaces for Skills and Memory.</p><ul><li>Similar to: third‑party APIs</li><li>Examples: GitHub MCP, Google Search MCP</li></ul><h3 id="packaging-and-orchestration" tabindex="-1">Packaging and Orchestration <a class="header-anchor" href="#packaging-and-orchestration" aria-label="Permalink to &quot;Packaging and Orchestration&quot;">​</a></h3><p>By combining the above layers into a minimal deliverable intelligent unit, you can version, permission, test, and iterate Agents just like traditional software.</p><h4 id="single-agent" tabindex="-1">Single Agent <a class="header-anchor" href="#single-agent" aria-label="Permalink to &quot;Single Agent&quot;">​</a></h4><p>Bundle the layers into a minimal shippable Agent.</p><ul><li>Similar to: software package or service</li><li>Examples: Email Assistant Agent, Research Assistant Agent</li></ul><h4 id="multi‐agent" tabindex="-1">Multi‑Agent <a class="header-anchor" href="#multi‐agent" aria-label="Permalink to &quot;Multi‑Agent&quot;">​</a></h4><p>Multiple Agents collaborate through scheduling/orchestration or autonomous coordination to complete complex tasks.</p><ul><li>Similar to: microservices architecture</li><li>Examples: customer support system with email, chat, and knowledge‑base Agents</li></ul><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  subgraph CA[Agent]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SI[System Instruction]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MS[Command]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AS[Skill]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MCP[MCP]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M[Memory]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  U(&#39;User&#39;) --&gt; CA</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SI --&gt; MS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SI --&gt; AS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  MCP --&gt; MS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  MCP --&gt; AS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  M[Memory] --&gt; MCP</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CA --&gt; Prompt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Prompt --&gt; LLM</span></span></code></pre></div><hr><blockquote><p>Reference: <a href="https://github.com/nibzard/awesome-agentic-patterns" target="_blank" rel="noreferrer">Awesome Agentic Patterns</a></p></blockquote><h2 id="outcome‐driven" tabindex="-1">Outcome‑Driven <a class="header-anchor" href="#outcome‐driven" aria-label="Permalink to &quot;Outcome‑Driven&quot;">​</a></h2><h3 id="why-outcome‐driven-matters" tabindex="-1">Why Outcome‑Driven Matters <a class="header-anchor" href="#why-outcome‐driven-matters" aria-label="Permalink to &quot;Why Outcome‑Driven Matters&quot;">​</a></h3><p>LLMs are inherently uncertain and black‑box; trial‑and‑error is not a smell but the normal path. That means every module must satisfy:</p><ul><li>Testable: you can verify that functionality works.</li><li>Reproducible: results have some degree of consistency.</li><li>Checkable: you can evaluate output quality.</li><li>Regressable: you can roll back versions and trace issues.</li></ul><p>Design and development should start from acceptance criteria and validation paths, then implement capability orchestration. If something is not testable, it is not fit for production.</p><h3 id="from-code-to-outcome" tabindex="-1">From &quot;Code&quot; to &quot;Outcome&quot; <a class="header-anchor" href="#from-code-to-outcome" aria-label="Permalink to &quot;From &quot;Code&quot; to &quot;Outcome&quot;&quot;">​</a></h3><p>If you treat prompts as a programming language, then what Agents generate are analogous to compiled artifacts in software engineering (like <code>.class</code> files). Most of the time, you do not need to stare at them; you should focus on outcomes — whether user goals are achieved and value is created. Obsessing over every detail of the &quot;code&quot; leads to micromanagement and kills leverage and innovation.</p><blockquote><p>&quot;Insist on not looking at any code other than CLAUDE.md. Eliminate micromanagement of AI. Using AI is an excellent way to practice servant leadership as a leader.&quot; — <a href="https://mp.weixin.qq.com/s/9qPD3gXj3HLmrKC64Q6fbQ" target="_blank" rel="noreferrer">Yuanming Hu · &quot;I Work for 10 Claude Code Agents&quot;</a></p></blockquote><h3 id="guard-the-architecture-let-go-of-the-code" tabindex="-1">Guard the Architecture, Let Go of the Code <a class="header-anchor" href="#guard-the-architecture-let-go-of-the-code" aria-label="Permalink to &quot;Guard the Architecture, Let Go of the Code&quot;">​</a></h3><p>This is the higher‑leverage way to work:</p><ul><li>Focus on outcomes and value, not line‑by‑line code control.</li><li>Constrain the system with boundaries and acceptance criteria, not micromanage execution.</li><li>Spend your attention on architecture, prioritization, and feedback loops — the high‑leverage decisions.</li></ul><h2 id="continuous-evolution" tabindex="-1">Continuous Evolution <a class="header-anchor" href="#continuous-evolution" aria-label="Permalink to &quot;Continuous Evolution&quot;">​</a></h2><h3 id="why-evolution-is-necessary" tabindex="-1">Why Evolution Is Necessary <a class="header-anchor" href="#why-evolution-is-necessary" aria-label="Permalink to &quot;Why Evolution Is Necessary&quot;">​</a></h3><p>An Agent should be a continuously evolving system, not a one‑off deliverable. You keep improving its capability and adaptability by:</p><ul><li>Iterative optimization: refine based on real usage feedback.</li><li>Feedback loops: deliberately collect and apply user feedback.</li><li>Version management: support canary releases, A/B tests, and fast rollback.</li></ul><h3 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h3><p>You need to plan for long‑term maintainability from day one:</p><ul><li>Maintainability: clear module boundaries and documentation.</li><li>Extensibility: reserve extension points and integration hooks for new capabilities.</li><li>Upgradability: avoid tech debt and over‑coupling.</li></ul><h2 id="personal-practice" tabindex="-1">Personal Practice <a class="header-anchor" href="#personal-practice" aria-label="Permalink to &quot;Personal Practice&quot;">​</a></h2><h3 id="github-copilot" tabindex="-1">GitHub Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;GitHub Copilot&quot;">​</a></h3><p>With <a href="https://code.visualstudio.com/docs/copilot/customization/overview" target="_blank" rel="noreferrer">Customize AI in Visual Studio Code</a>, Copilot already supports most Agentic techniques, including:</p><ul><li><code>.github/copilot-instructions.md</code> = System Instruction</li><li><code>.github/prompts/*.prompt.md</code> = Command</li><li><code>.github/skills/*/SKILL.md</code> = Skill</li><li>MCP &amp; Custom Agents</li></ul><p>Without changing the development environment, you can gradually build Agentic workflows via custom instructions, and eventually replace most repetitive work. For example: <code>/test-golang</code>, <code>/code-review</code>, <code>/debug-kubernetes</code>, <code>/get-my-jira-tickets</code> …</p><h3 id="memory-1" tabindex="-1">Memory <a class="header-anchor" href="#memory-1" aria-label="Permalink to &quot;Memory&quot;">​</a></h3><p>Memory stores user preferences, history, and context so that interactions across sessions stay coherent. Implementation options include:</p><ul><li>File system: store memory in files under a specific path; pass the path as input.</li><li>File system + Skills: provide skills for reading/writing memory without exposing concrete paths (e.g. OpenSpec).</li><li>MCP: store memory in an external system (database) and access it via MCP (e.g. OpenMemory).</li></ul><hr><blockquote><p>🤖 Suggested prompts for AI:</p><ul><li>&quot;Difference between Commands and Skills&quot;</li><li>&quot;Versioning and rollback strategies for Agents&quot;</li><li>&quot;How to test and evaluate Agent output quality&quot;</li></ul></blockquote>`,63)])])}const m=a(o,[["render",s]]);export{h as __pageData,m as default};
